-- =====================================================================
-- Baseline metric import — generated by scripts/db/import-snapshot.mjs
-- Source: snapshot/baseline.json (134 metrics)
--
-- Apply ONCE, by hand, as the database owner, after every migration and
-- before any publishing. This is not a migration and must not be applied
-- automatically.
--
-- Private fields (source_reference, attribution_setting, internal_note) are
-- not in the snapshot and stay empty. No metric is marked verified: the
-- verification record is only ever written by a person confirming a figure
-- against its source, so every imported metric starts as "Not verified".
-- The import writes one version-history row and one audit entry per metric.
-- =====================================================================

begin;

do $$
begin
  if exists (select 1 from public.metrics) then
    raise exception 'public.metrics is not empty; review before importing the baseline';
  end if;
end
$$;


do $$
declare
  v_count integer;
begin
  select count(*) into v_count from public.metrics;
  if v_count <> 134 then
    raise exception 'expected 134 metrics after import, found %', v_count;
  end if;
end
$$;

commit;
